function lmToast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(lmToast.timer);lmToast.timer=setTimeout(()=>$('toast').classList.remove('show'),3400);$('status').textContent=text;}
function lmLog(kind,extra={}){if(!LM.recording)return;if(LM.events.length>=20000){LM.recording=false;lmToast('記錄已達 20,000 個事件，請先匯出。');lmUI();return;}LM.events.push({elapsed_ms:Math.round(performance.now()-LM.started),event:kind,source_id:LM.sourceId,state:lmSnapshot(),conditions:{width:LM.W,height:LM.H,sampling_step:LM.step,samples:LM.points.length,view:LM.compare?'comparison':'single',pointer_enabled:LM.interactive},...extra});if(lmRoot)$('record-status').textContent='本機記錄中 · '+LM.events.length+' 個事件';}
