function lmRebuild(){if(!LM.source)return;const step=Math.max(LM.p.spacing,Math.sqrt(LM.W*LM.H/10000));const cols=Math.max(1,Math.floor(LM.W/step)),rows=Math.max(1,Math.floor(LM.H/step));const c=document.createElement('canvas');c.width=cols;c.height=rows;const ctx=c.getContext('2d',{willReadFrequently:true}),r=lmRect();ctx.drawImage(LM.source,r.x/LM.W*cols,r.y/LM.H*rows,r.w/LM.W*cols,r.h/LM.H*rows);const d=ctx.getImageData(0,0,cols,rows).data;const lum=(x,y)=>{const i=(lmClamp(y,0,rows-1)*cols+lmClamp(x,0,cols-1))*4;return d[i+3]?(.2126*d[i]+.7152*d[i+1]+.0722*d[i+2])/255:0;};LM.points=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const i=(y*cols+x)*4;if(d[i+3]<16)continue;let l=lum(x,y);if(LM.invert)l=1-l;l=Math.pow(lmClamp((l-.5)*LM.p.contrast+.5+LM.p.exposure/255,0,1),1/LM.p.gamma);if(l*255<=LM.p.threshold)continue;LM.points.push({id:y*cols+x,x:(x+.5)/cols*LM.W,y:(y+.5)/rows*LM.H,l,r:d[i],g:d[i+1],b:d[i+2],a:Math.atan2(lum(x,y+1)-lum(x,y-1),lum(x+1,y)-lum(x-1,y))+Math.PI/2});}LM.step=step;LM.dirty=true;redraw();}
