function lmPaint(ctx,w,h,s,t,mode=s.mode,original=false,transparent=false,pointer=null){ctx.save();ctx.clearRect(0,0,w,h);if(!transparent){ctx.fillStyle=s.bg;ctx.fillRect(0,0,w,h);}ctx.scale(w/LM.W,h/LM.H);const r=lmRect();if(original||s.p.sourceMix>0){ctx.globalAlpha=original?1:s.p.sourceMix;ctx.drawImage(LM.source,r.x,r.y,r.w,r.h);ctx.globalAlpha=1;}if(!original){const marks=lmMarks(LM.points,{...s,step:LM.step,W:LM.W,H:LM.H},t,mode,pointer);ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineCap='round';for(const m of marks){ctx.globalAlpha=m.alpha;ctx.fillStyle=ctx.strokeStyle=m.color;if(m.kind==='line'){ctx.lineWidth=m.weight;ctx.beginPath();ctx.moveTo(m.x,m.y);ctx.lineTo(m.x2,m.y2);ctx.stroke();}else if(m.kind==='dot'){ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);ctx.fill();}else{ctx.save();ctx.translate(m.x,m.y);ctx.rotate(m.angle);ctx.font=m.size+'px monospace';ctx.fillText(m.text,0,0);ctx.restore();}}}ctx.restore();}
