 for(const key of ['chars','ink','bg','aspect','invert','transparent'])$(key).onchange=()=>{const el=$(key);LM[key]=el.type==='checkbox'?el.checked:el.value;if(key==='chars')LM.chars=Array.from(LM.chars.trim()).slice(0,48).join('')||'·一十未定之像';if(key==='aspect')lmDimensions();lmChange(key);};
